import React, { useState, useRef } from 'react';
import { useAuth } from '../context/AuthContext.jsx';
import MainLayout from '../components/layout/MainLayout';
import GameConstructor from '../components/gameEngine/GameConstructor.jsx';

function HomePage() {
  const { currentUser, logout } = useAuth();
  const [showGameConstructor, setShowGameConstructor] = useState(false);
  const gameRef = useRef(null); // ссылка на элемент

  const toggleGameConstructor = () => {
    const willShow = !showGameConstructor;
    setShowGameConstructor(willShow);

    // Если мы только что показали компонент — прокрутим к нему
    if (willShow) {
      // Небольшая задержка, чтобы React успел отрендерить DOM
      setTimeout(() => {
        if (gameRef.current) {
          gameRef.current.scrollIntoView({
            behavior: 'smooth', // плавная анимация
            block: 'start'      // выравнивание по верху
          });
        }
      }, 50); // 50 мс обычно достаточно
    }
  };

  return (
    <MainLayout>
      <div className="homepage">
        <h1>Добро пожаловать в WordPallete!</h1>
        <p>Привет, {currentUser?.email}!</p>
        <button onClick={logout} className="logout-btn">
          Выйти
        </button>

        <div className="features">
          <h2>Возможности приложения:</h2>
          <ul>
            <li>
              <button onClick={toggleGameConstructor} className="feature-btn">
                Генерация креативных слов и фраз
              </button>
            </li>
            <li>Сохранение ваших любимых комбинаций</li>
            <li>Работа в разных категориях</li>
          </ul>
        </div>

        {/* Оборачиваем GameConstructor в div с ref */}
        {showGameConstructor && (
          <div ref={gameRef}>
            <GameConstructor />
          </div>
        )}
      </div>
    </MainLayout>
  );
}

export default HomePage;
